# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/schedules_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.SchedulesTest do
  use ExUnit.Case, async: true

  alias JoobQ.Schedules

  test "a cron schedule's body names the job, its queue, its timing and the gateway's fields" do
    body = Schedules.body("nightly", "mail", "digest", cron: "0 3 * * *", payload: %{"d" => 1})

    assert body == %{
             "name" => "nightly",
             "kind" => "job",
             "cron" => "0 3 * * *",
             "timezone" => "UTC",
             "queue" => "mail",
             "job_type" => "digest",
             "payload" => %{"d" => 1}
           }

    every =
      Schedules.body("tick", "mail", "ping",
        every: "30 seconds",
        timezone: "Europe/Paris",
        max_retries: 0
      )

    assert %{"every" => "30 seconds", "timezone" => "Europe/Paris", "max_retries" => 0} = every
    refute Map.has_key?(every, "cron")
  end

  test "exactly one of :cron and :every, and every option checked without printing its value" do
    for opts <- [[], [cron: "* * * * *", every: "5 minutes"], [cron: nil]] do
      assert_raise ArgumentError, ~r/exactly one/, fn -> Schedules.body("s", "q", "t", opts) end
    end

    error =
      assert_raise ArgumentError, fn -> Schedules.body("s", "q", "t", cron: 5, secret: 1) end

    assert error.message =~ ":secret"

    assert_raise ArgumentError, ~r/:max_retries/, fn ->
      Schedules.body("s", "q", "t", every: "1 hour", max_retries: 101)
    end

    error =
      assert_raise ArgumentError, fn ->
        Schedules.body(%{"k" => "hunter2"}, "q", "t", every: "1 hour")
      end

    refute error.message =~ "hunter2"
  end
end
